package com.jmadsen.dashhop;
import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class DirectOpenMeteoProvider implements WeatherProvider {
 static final class HttpError extends IOException {final int status;HttpError(int status){super("Weather HTTP status");this.status=status;}}
 final boolean commercial;final String key;DirectOpenMeteoProvider(){this(false,"");}DirectOpenMeteoProvider(boolean commercial,String key){this.commercial=commercial;this.key=key;}
 public String source(){return "Open-Meteo (direct)";}public boolean available(){return true;}
 static void coordinates(double lat,double lon){if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IllegalArgumentException("Invalid coordinates");}
 public WeatherData fetch(double lat,double lon,String place)throws Exception{coordinates(lat,lon);if(commercial&&key.isEmpty())throw new IllegalStateException("Commercial weather key missing");String url=(commercial?"https://customer-api.open-meteo.com":"https://api.open-meteo.com")+"/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,apparent_temperature,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code,precipitation_probability&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&timeformat=unixtime&forecast_days=7";if(commercial)url+="&apikey="+java.net.URLEncoder.encode(key,"UTF-8");return new WeatherData(new JSONObject(get(url)),place,System.currentTimeMillis());}
 static String get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","DashHopper/2.0.2");try{int status=c.getResponseCode();if(status!=200)throw new HttpError(status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>1000000)throw new IOException("Weather response too large");out.write(b,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}finally{c.disconnect();}}
 static JSONArray cities(String query,boolean commercial,String key)throws Exception{if(commercial&&key.isEmpty())throw new IllegalStateException("Commercial weather key missing");String url=(commercial?"https://customer-geocoding-api.open-meteo.com":"https://geocoding-api.open-meteo.com")+"/v1/search?name="+URLEncoder.encode(query,"UTF-8")+"&count=8&language=en&format=json";if(commercial)url+="&apikey="+URLEncoder.encode(key,"UTF-8");return new JSONObject(get(url)).optJSONArray("results");}
}
